"N26D1-Q102":{"banca":[["😢 Contrariada → chora → prende o ar → fica azul","😌 Perda de fôlego cianótica: tranquilizar"],["🤕 Susto ou dor leve → fica pálida e desmaia","😌 Perda de fôlego pálida: também benigna"],["😴 Episódio sem gatilho ou durante o sono","🧠 Pensar em epilepsia: EEG"],["🏃 Síncope ao esforço ou morte súbita na família","❤️ Pensar em arritmia: ECG"]],"mini":{"doenca":"😮 Crise de perda de fôlego","paciente":"🧒 Criança de 6 meses a 6 anos","sintomas":"😢 Choro • 😶 apneia em expiração • 🔵 cianose • 😵 perda breve do tônus","diagnostico":"🩺 Clínico, pela história","exames":"🧪 Hemograma e ferritina (anemia ferropriva piora as crises)","tratamento":"😌 Tranquilizar • 🛏️ deitar de lado e esperar • 💊 ferro se houver deficiência","complicacoes":"-","nunca":"❌ Ceder ao que a criança queria para evitar a crise","pegadinha":"🎯 Some sozinha até os 6 anos"}},
"N26D1-Q103":{"banca":[["🧒 6 anos ou mais com TDAH","💊 Metilfenidato ou dexanfetamina"],["👶 Menor de 6 anos","👨‍👩‍👧 Treino de pais primeiro"],["🚫 Estimulante falhou ou não foi tolerado","💊 Atomoxetina, guanfacina ou clonidina"],["😬 Tiques ou insônia importantes","💊 Preferir clonidina ou guanfacina"]],"mini":{"doenca":"⚡ Transtorno de déficit de atenção e hiperatividade","paciente":"🧒 Menino em idade escolar","sintomas":"😶 Desatenção • 🏃 hiperatividade • ⏱️ impulsividade, em dois ambientes","diagnostico":"🩺 Clínico, com relato de pais e professores","exames":"-","tratamento":"💊 Estimulante • 👨‍👩‍👧 treino de pais • 🏫 apoio na escola","complicacoes":"📉 Fracasso escolar • 🤕 acidentes • 😔 baixa autoestima","nunca":"❌ Começar estimulante sem medir peso, altura, pulso e pressão","pegadinha":"🎯 O estimulante tira o apetite: acompanhar o crescimento"}},
"N26D1-Q104":{"banca":[["👶 Colapso na 1ª semana + pulso femoral ausente","❤️ Coarctação ou coração esquerdo hipoplásico"],["🔵 Cianose desde o nascimento que não melhora com oxigênio","❤️ Transposição das grandes artérias"],["📅 Sintoma entre 4 e 8 semanas + ganho de peso ruim","❤️ Shunt esquerda-direita (CIV)"],["🌡️ Febre ou hipotermia + letargia, pulsos iguais","🦠 Sepse"]],"mini":{"doenca":"❤️ Coarctação de aorta crítica","paciente":"👶 Recém-nascido de 3 a 10 dias • 👧 síndrome de Turner","sintomas":"😮 Taquipneia • 🍼 recusa alimentar • ⚪ palidez • 📉 choque","diagnostico":"📊 Ecocardiograma","exames":"📉 Saturação menor no pé • 📏 pressão menor na perna que no braço direito","tratamento":"💉 Prostaglandina E1 para reabrir o canal • 🔪 correção cirúrgica","complicacoes":"📉 Choque cardiogênico • 🧂 insuficiência renal • 💩 enterocolite necrosante","nunca":"❌ Dar alta de um recém-nascido sem palpar os pulsos femorais","pegadinha":"🎯 Na criança maior, o achado é hipertensão no braço com pulso femoral atrasado"}},
"N26D1-Q105":{"banca":[["🚑 Gestante com trauma grave, qualquer idade gestacional","📷 TC conforme a indicação materna"],["📅 23 a 24 semanas ou mais, após trauma","📈 CTG por pelo menos 4 horas"],["📅 Menos de 23 semanas","🚫 CTG não se aplica"],["🩸 Mãe Rh negativo após trauma","💉 Imunoglobulina anti-D"]],"mini":{"doenca":"🚑 Trauma na gestante","paciente":"🤰 Gestante após acidente de trânsito, queda ou agressão","sintomas":"😖 Dor conforme a lesão • 🩸 sangramento vaginal • 💧 perda de líquido","diagnostico":"📷 Imagem guiada pela lesão materna","exames":"🧪 Tipagem e Kleihauer • 📈 CTG se já viável","tratamento":"🛏️ Estabilizar a mãe primeiro • ↩️ deslocar o útero para a esquerda após 20 semanas • 💉 anti-D se Rh negativo","complicacoes":"🩸 Descolamento de placenta • 👶 parto prematuro • 💥 rotura uterina","nunca":"❌ Adiar imagem necessária por causa da gravidez","pegadinha":"🎯 Caiu três vezes no mesmo dia (Q33, Q105 e Q123)"}},
