"N26D1-Q115":{"banca":[["💉 Bradicardia fetal logo após a peridural","💧 Lateral esquerdo + fluido + vasopressor"],["⏱️ Bradicardia com mais de 5 contrações em 10 minutos","🛑 Parar a ocitocina e dar tocolítico"],["💧 Bradicardia logo após romper a bolsa","🚨 Procurar prolapso de cordão"],["🚨 Persiste apesar das medidas","🔪 Cesárea de emergência"]],"mini":{"doenca":"📉 Bradicardia fetal após peridural","paciente":"🤰 Parturiente nos minutos seguintes ao bloqueio","sintomas":"📉 Pressão materna baixa • 🤢 náusea • 📉 frequência fetal abaixo de 100","diagnostico":"📈 CTG + pressão materna","exames":"-","tratamento":"↩️ Lateral esquerdo • 💧 fluido • 💉 vasopressor • 🔪 cesárea se não recuperar","complicacoes":"👶 Hipóxia fetal","nunca":"❌ Retirar o cateter achando que resolve","pegadinha":"🎯 Dar fluido antes do bloqueio reduz a hipotensão"}},
